(()=>{
 const el=id=>document.getElementById(id),local=s=>new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'});let api='',dirty=false,config={intervalDays:7,time:'00:00'};
 const message=(id,text)=>{el(id).textContent=text};
 async function request(path,body,secret){const r=await fetch(api+path,{method:body===undefined?'GET':'POST',headers:{...(body===undefined?{}:{'content-type':'application/json'}),...(secret?{authorization:'Bearer '+secret}:{})},body:body===undefined?undefined:JSON.stringify(body),cache:'no-store'});const result=await r.json();if(!r.ok)throw Error(result.error||'云端操作未完成');return result}
 function show(c,force=false){config=c;el('automationTitle').dataset.schedule=`每隔${c.intervalDays||7}天，北京时间${c.time||'00:00'}启动`;if(!dirty||force){el('intervalDays').value=String(c.intervalDays||7);const [h,m]=(c.time||'00:00').split(':');el('runHour').value=h;el('runMinute').value=m;}message('scheduleState',`云端计划：每隔${c.intervalDays||7}天，北京时间${c.time||'00:00'}。${c.nextRunAt?'下一次：'+local(c.nextRunAt):''}`)}
 async function refresh(){try{const state=await request('/public/status');show(state.config);el('subscribeButton').disabled=!state.mailReady;message('mailState',state.mailReady?'填写邮箱后，我们会先发确认邮件；确认后开始接收新品。':'邮件服务尚在连接，订阅尚未启用，不会虚报发送成功。');const m=state.monitor;message('monitorState',`${m.state==='active'?'全天监测中':m.state==='error'?'最近一轮监测未完成':'监测尚未启动'} · 每15分钟检查一次${m.lastSuccess?' · 最近成功检查：'+local(m.lastSuccess):''}${m.lastError?' · '+m.lastError:''}。发现后立即进入邮件发送队列。`)}catch(e){message('monitorState','云端监测服务暂时不可达：'+e.message)}}
 el('scheduleForm').addEventListener('change',()=>{dirty=true});
 el('scheduleForm').addEventListener('submit',async e=>{e.preventDefault();const days=el('intervalDays').value||'7',time=el('intervalDays').value?el('runHour').value+':'+el('runMinute').value:'00:00';el('saveSchedule').disabled=true;try{if(!api)throw Error('云端设置服务尚未连接；当前仍执行已公布的默认7天00:00计划。');const secret=el('adminCode').value.trim();if(!secret)throw Error('请输入管理员访问码，防止其他访客修改你的云端更新计划。');const result=await request('/admin/schedule',{intervalDays:Number(days),time},secret);dirty=false;show(result.config,true);message('scheduleResult',result.message);el('adminCode').value=''}catch(err){message('scheduleResult',err.message)}finally{el('saveSchedule').disabled=false}});
 el('subscribeForm').addEventListener('submit',async e=>{e.preventDefault();el('subscribeButton').disabled=true;try{if(!api)throw Error('邮件服务尚未连接，尚未保存订阅。');const scopes=[...document.querySelectorAll('input[name=mailScope]:checked')].map(x=>x.value);if(!scopes.length)throw Error('请至少选择圣诞树或树裙。');const result=await request('/subscribe',{email:el('subscriberEmail').value.trim(),scopes});message('subscribeResult',result.message);el('subscriberEmail').value=''}catch(err){message('subscribeResult',err.message)}finally{el('subscribeButton').disabled=!api}});
 async function init(){try{const [service,saved]=await Promise.all([fetch('service.json',{cache:'no-store'}).then(r=>r.json()),fetch('settings.json',{cache:'no-store'}).then(r=>r.json())]);show(saved);api=(service.apiBase||'').replace(/\/$/,'');if(api){await refresh();setInterval(refresh,60000)}else{message('monitorState','全天新品监测：云端邮件服务连接完成后启用，目标每15分钟检查一次。');message('mailState','邮件服务尚在连接，订阅尚未启用，不会虚报发送成功。');el('subscribeButton').disabled=true}}catch(e){message('scheduleState','读取云端计划失败，请刷新重试。')}}
 init();
})();
